function setup() {
	createCanvas(600, 600);
}


function draw() {
	background("beige")




	noStroke()
	for (let x = 0; x < width;) {
		const swX = width * random(0.02, 0.1);
		fill(random(["grey", "white", "yellow", 64]))
		rect(x, 0, swX, height)
		x += swX * 2
	}

	for (let y = 0; y < height;) {
		const swY = height * random(0.01, 0.05);
		fill(random(["grey", "white", "yellow", 64]))
		rect(0, y, height, swY)
		y += swY * 2
	}


	// noLoop() removed for animation
}
